4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * The single duplicate check for creating an owner: rejects 409 when the new owner's whole
10	 * {@link Owner#getIdentityKey() identityKey} — {@code normalizedTelephone|email|householdId} —
11	 * equals an existing owner's. This consolidates the former separate telephone, email and household
12	 * checks into one derived key, so a create is a duplicate only on an exact full-key match. Because
13	 * the telephone is part of the key, two members of the same household (same {@code householdId})
14	 * with different telephones have different keys and are both allowed.
15	 *
16	 * <p>Runs after {@link BuildOwner} and {@link AssignOwnerHousehold} have produced the entity and
17	 * resolved its {@code householdId}, so both sides of the comparison are reduced to canonical form
18	 * through the same {@link Owner#getIdentityKey()} and can never drift. The new owner is not yet
19	 * persisted, so {@link OwnerRepository#findAll()} yields only the other owners.
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = owner.getIdentityKey();
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
28	                continue;
29	            }
30	            if (identityKey.equals(existing.getIdentityKey())) {
31	                throw new DuplicateIdentityException(
32	                        "An owner with the same identity key already exists");
33	            }
34	        }
35	    }
36	}
